"""Stable public image-to-text API for Kutarya Lens."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from virvision.config import Config, load_config
from virvision.kcs.model import KCS_VERSION, KCSMetrics
from virvision.kcs.runtime import KCSProfile, ExecutionPlan, compile_execution_plan
from virvision.perception import create_pipeline
from virvision.perception.pipeline import PerceptionPipeline, PerceptionTimings
from virvision.perception.profiling import ResourceMetrics
from virvision.scene import VisualScene, scene_to_dict


@dataclass(frozen=True)
class LensMetrics:
    perception: PerceptionTimings
    kcs: KCSMetrics
    resources: ResourceMetrics
    total_processing_ms: float

    def to_dict(self) -> dict:
        return {
            "perception_ms": self.perception.to_dict(),
            "kcs_ms": self.kcs.to_dict(),
            "resources": self.resources.to_dict(),
            "total_processing_ms": self.total_processing_ms,
        }


@dataclass(frozen=True)
class LensResult:
    """Natural text plus the evidence scene, measurements, and explicit warnings."""

    text: str
    scene: VisualScene
    metrics: LensMetrics
    warnings: tuple[str, ...]
    language: str
    detail: str

    def to_dict(self) -> dict:
        return {
            "text": self.text,
            "objects": len(self.scene.objects),
            "ocr_items": len(self.scene.texts),
            "relations": len(self.scene.relations),
            "processing_ms": self.metrics.total_processing_ms,
            "warnings": list(self.warnings),
            "language": self.language,
            "detail": self.detail,
            "kcs_version": KCS_VERSION,
            "metrics": self.metrics.to_dict(),
            "scene": scene_to_dict(self.scene),
        }


class Lens:
    """Analyze a local image and return grounded natural-language visual context."""

    def __init__(
        self,
        config_path: str | Path | None = None,
        *,
        config: Config | None = None,
        perception_pipeline: PerceptionPipeline | None = None,
        execution_plan: ExecutionPlan | None = None,
    ) -> None:
        if config_path is not None and config is not None:
            raise ValueError("provide config_path or config, not both")
        self.config = config or load_config(Path(config_path) if config_path is not None else None)
        self._perception = perception_pipeline or create_pipeline(self.config.perception)
        profile = KCSProfile(
            language=self.config.lens.language,
            detail=self.config.lens.detail,
            spatial=self.config.spatial,
        )
        self._execution_plan = execution_plan or compile_execution_plan(
            profile, thresholds=self.config.confidence
        )

    @property
    def kcs_version(self) -> str:
        return KCS_VERSION

    def analyze(
        self,
        image: str | Path,
        *,
        language: str | None = None,
        detail: str | None = None,
    ) -> LensResult:
        """Run local perception and return a grounded text description."""
        perception = self._perception.analyze(Path(image))
        run = self._execution_plan.execute(perception.scene, language=language, detail=detail)
        metrics = LensMetrics(
            perception.timings,
            run.metrics,
            perception.resources,
            perception.timings.total_pre_llm_ms + run.metrics.runtime_total_ms,
        )
        return LensResult(
            run.text,
            run.field.scene,
            metrics,
            run.projection.warnings,
            run.projection.language,
            run.projection.detail,
        )
